 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    spine_rows = [r for r, cols in by_row.items() if len(cols) >= 2]
    if not spine_rows:
        return out
    # The pair of markers on one row defines the horizontal spine.
    spine = spine_rows[0]
    left, right = min(by_row[spine]), max(by_row[spine])
    for c in range(left + 1, right):
        if out[spine][c] == 0:
            out[spine][c] = 3
    # Join each remaining marker to the spine along its own column.
    for r, c in points:
        if r < spine:
            for rr in range(r + 1, spine):
                if out[rr][c] == 0:
                    out[rr][c] = 3
        elif r > spine:
            for rr in range(spine + 1, r):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out
